mapper.select:
SELECT p.*, c.name AS category_name, (SELECT COUNT(*) FROM product_sku s WHERE s.product_id = p.id AND s.is_deleted = false) AS sku_count, image.attachment_id AS cover_image_attachment_id FROM product p JOIN product_category c ON c.id = p.category_id AND c.is_deleted = false LEFT JOIN product_image image ON image.owner_id = p.id AND image.image_type = 'PRODUCT' AND image.is_cover = true AND image.is_deleted = false WHERE p.is_deleted = false AND p.status = #{query.status}
AND p.category_id IN #{id}
AND (p.name ILIKE CONCAT('%', #{query.keyword}, '%') OR p.code ILIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS (SELECT 1 FROM product_sku s WHERE s.product_id = p.id AND s.is_deleted = false AND (s.code ILIKE CONCAT('%', #{query.keyword}, '%') OR s.model ILIKE CONCAT('%', #{query.keyword}, '%'))))
ORDER BY p.sort_order, p.id
